#include <stdio.h>
#include <unistd.h>

struct user { char name[16]; int is_admin; };

int main(void) {
    struct user u = { .is_admin = 0 };
    setvbuf(stdout, NULL, _IONBF, 0);
    puts("Логин:");
    read(0, u.name, 32);
    if (u.is_admin == 0x1337) {
        char flag[64];
        FILE *f = fopen("flag.txt", "r");
        if (f && fgets(flag, sizeof flag, f)) puts(flag);
    } else {
        printf("Привет, обычный пользователь. is_admin = 0x%x\n", u.is_admin);
    }
    return 0;
}
